1	// A small REST client for Directus's own API — deliberately free of any `@pulumi/*` import so it's
2	// unit testable (see resources.ts, whose dynamic resource providers call into here; importing
3	// resources.ts itself isn't practical since its module-level imports pull in Pulumi).
4	
5	// This package's tsconfig (@tsconfig/node20, lib: es2023, no DOM) hits an @types/node quirk where
6	// the ambient `fetch`/`Response` types resolve to an empty structural type rather than undici's
7	// real one (its conditional type meant to defer to DOM lib's Response misfires with no DOM lib
8	// present either). Rather than cast at every call site, wrap `fetch` once with the shape we
9	// actually use.
10	export interface HttpResponse {
11	  readonly ok: boolean;
12	  readonly status: number;
13	  text(): Promise<string>;
14	  json(): Promise<unknown>;
15	}
16	
17	export async function httpFetch(input: string, init?: RequestInit): Promise<HttpResponse> {
18	  return (await fetch(input, init)) as unknown as HttpResponse;
19	}
20	
21	/** Default timeout for {@link waitForReachable}. Callers now `dependsOn` substrate-apply.ts, so this
22	 * is a safety net for container start/migration time, not a VM-boot budget (was 180s) - kept above
23	 * typical Directus startup so it doesn't reintroduce flaky applies. */
24	export const DEFAULT_REACHABLE_TIMEOUT_MS = 90_000;
25	
26	export async function waitForReachable(baseUrl: string, timeoutMs = DEFAULT_REACHABLE_TIMEOUT_MS): Promise<void> {
27	  const start = Date.now();
28	  let lastError: unknown;
29	  while (Date.now() - start < timeoutMs) {
30	    try {
31	      const res = await httpFetch(`${baseUrl}/server/ping`);
32	      if (res.ok) return;
33	    } catch (error) {
34	      lastError = error;
35	    }
36	    await new Promise((resolve) => setTimeout(resolve, 5_000));
37	  }
38	  throw new Error(
39	    `Directus at ${baseUrl} did not become reachable within ${timeoutMs}ms (VM boot/DNS/TLS may still be in ` +
40	      `progress — re-run \`pulumi up\` once it's up). Last error: ${String(lastError)}`,
41	  );
42	}
43	
44	export async function login(baseUrl: string, email: string, password: string): Promise<string> {
45	  const res = await httpFetch(`${baseUrl}/auth/login`, {
46	    method: "POST",
47	    headers: { "Content-Type": "application/json" },
48	    body: JSON.stringify({ email, password }),
49	  });
50	  if (!res.ok) {
51	    throw new Error(`Directus login as ${email} failed: ${res.status} ${await res.text()}`);
52	  }
53	  return ((await res.json()) as { data: { access_token: string } }).data.access_token;
54	}
55	
56	/** Thrown by {@link directusRequest} on a non-2xx response, with `status` broken out so callers can
57	 * tell "not found" apart from a real failure without string-matching the message. */
58	export class DirectusHttpError extends Error {
59	  constructor(
60	    public readonly status: number,
61	    message: string,
62	  ) {
63	    super(message);
64	    this.name = "DirectusHttpError";
65	    // Required, not cosmetic. Pulumi runs a dynamic provider in a separate process through its own
66	    // vendored ts-node, which downlevels `class ... extends Error` and breaks the prototype chain -
67	    // so `message` and `instanceof` are both lost on the way out. A real failure surfaced as
68	    // `error: undefined` until this line existed.
69	    Object.setPrototypeOf(this, DirectusHttpError.prototype);
70	    // Same reason, second half: `message` and `stack` are non-enumerable on Error, so Pulumi's
71	    // serialization of a thrown value across the provider boundary drops them and leaves an object
72	    // carrying only `status`. Redefining `message` as enumerable is what makes it survive.
73	    Object.defineProperty(this, "message", { value: message, enumerable: true, writable: true, configurable: true });
74	  }
75	}
76	
77	/** True if `error` is a {@link DirectusHttpError} for a 404 — the shared "already gone" check every
78	 * tolerant delete uses to tell "not found" apart from a real failure. */
79	export function isNotFound(error: unknown): boolean {
80	  return error instanceof DirectusHttpError && error.status === 404;
81	}
82	
83	/** True if `error` is a {@link DirectusHttpError} for a 403. Directus answers 403 rather than 404
84	 * for a `/users/{id}` that doesn't exist (see {@link userExists}), so a tolerant delete on `/users`
85	 * has to treat this the same as {@link isNotFound}. */
86	export function isForbidden(error: unknown): boolean {
87	  return error instanceof DirectusHttpError && error.status === 403;
88	}
89	
90	function errorMessage(error: unknown): string | undefined {
91	  const message = (error as { message?: unknown } | null)?.message;
92	  return typeof message === "string" && message.length > 0 ? message : undefined;
93	}
94	
95	function errorStatus(error: unknown): number | undefined {
96	  const status = (error as { status?: unknown } | null)?.status;
97	  return typeof status === "number" ? status : undefined;
98	}
99	
100	function errorStack(error: unknown): string | undefined {
101	  const stack = (error as { stack?: unknown } | null)?.stack;
102	  return typeof stack === "string" ? stack : undefined;
103	}
104	
105	/**
106	 * Normalizes whatever a Directus dynamic-provider method throws into a plain `Error` with a
107	 * non-empty message, naming the provider and method that failed.
108	 *
109	 * A dynamic provider runs in a separate process through Pulumi's own vendored ts-node, which
110	 * downlevels `class ... extends Error` and can drop `message` on the way out (see
111	 * `DirectusHttpError` above) - and a bare `throw "reason"` or `throw undefined` loses everything
112	 * regardless. Call this at each provider method's outer boundary, after any internal handling
113	 * (e.g. `DirectusUser.update`'s 404 re-resolution) has already run its own `instanceof` checks on
114	 * the original error - this only sees whatever escapes that.
115	 */
116	export function describeProviderError(resource: string, method: string, error: unknown): Error {
117	  const message = errorMessage(error);
118	  const status = errorStatus(error);
119	  const stack = errorStack(error);
120	  const detail = message ?? (stack !== undefined ? `${String(error)}\n${stack}` : String(error));
121	  const withStatus = status !== undefined ? `${detail} (status ${status})` : detail;
122	  return new Error(`${resource}.${method} failed: ${withStatus}`);
123	}
