125	export async function directusRequest<T>(
126	  baseUrl: string,
127	  token: string,
128	  method: string,
129	  path: string,
130	  body?: unknown,
131	): Promise<T> {
132	  const res = await httpFetch(`${baseUrl}${path}`, {
133	    method,
134	    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
135	    body: body !== undefined ? JSON.stringify(body) : undefined,
136	  });
137	  if (!res.ok) {
138	    throw new DirectusHttpError(res.status, `${method} ${path} -> ${res.status}: ${await res.text()}`);
139	  }
140	  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
141	}
