46	
47	export function diffFields<Row extends { id?: string }>(existing: Row, desired: Omit<Row, "id">): Partial<Row> {
48	  const existingFields = existing as Record<string, unknown>;
49	  const desiredFields = desired as Record<string, unknown>;
50	  const patch: Record<string, unknown> = {};
51	  for (const key of Object.keys(desiredFields)) {
52	    if (existingFields[key] !== desiredFields[key]) {
53	      patch[key] = desiredFields[key];
54	    }
55	  }
56	  return patch as Partial<Row>;
57	}
