60	export function planByKey<Row extends { id?: string }>(
61	  desired: DesiredRow<Row>[],
62	  existing: Row[],
63	  keyField: keyof Row,
64	): CollectionPlan<Row> {
65	  const existingByKey = new Map<string, Row>();
66	  for (const row of existing) {
67	    const key = (row as Record<string, unknown>)[keyField as string];
68	    if (typeof key === "string") {
69	      existingByKey.set(key, row);
70	    }
71	  }
72	
73	  const toCreate: Omit<Row, "id">[] = [];
74	  const toUpdate: { id: string; patch: Partial<Row> }[] = [];
