1	import { calendar_v3, google } from "googleapis";
2	import { Auth } from "googleapis";
3	import { DateTime } from "luxon";
4	import winston from "winston";
5	
6	/**
7	 * Represents a calendar event
8	 */
9	export interface CalendarEvent {
10	  /** Unique identifier for the event */
11	  id: string;
12	  title: string;
13	  startTime: DateTime;
14	  endTime: DateTime;
15	  allDay: boolean;
16	  description?: string;
17	  location?: string;
18	  /** Additional metadata */
19	  metadata?: Record<string, string> | undefined;
20	}
21	
22	/**
23	 * Google Calendar API client
24	 */
25	export class CalendarClient {
26	  private client: calendar_v3.Calendar;
27	
28	  constructor(auth: Auth.GoogleAuth) {
29	    this.client = google.calendar({ version: "v3", auth } as any);
30	  }
31	
32	  public loadCalendar(calendarId: string): Calendar {
33	    return new Calendar(this.client, calendarId);
34	  }
35	}
36	
37	export class Calendar {
38	  constructor(
39	    private client: calendar_v3.Calendar,
40	    public readonly calendarId: string,
41	  ) {}
42	
43	  /**
44	   * Gets a single event by ID
45	   * Returns null if the event doesn't exist
46	   */
47	  async getEvent(eventId: string): Promise<CalendarEvent | null> {
48	    winston.debug("Getting calendar event", { calendar: this.calendarId, eventId });
49	
50	    try {
51	      const response = await this.client.events.get({
52	        calendarId: this.calendarId,
53	        eventId,
54	      });
55	
56	      if (!response.data.id || response.data.status === "cancelled") {
57	        return null;
58	      }
59	
60	      winston.debug("Found calendar event", { eventId: response.data.id });
61	      return convertToCalendarEvent(response.data);
62	    } catch (error: any) {
63	      // If event doesn't exist, return null instead of throwing
64	      if (error.code === 404) {
65	        winston.debug("Event not found", { eventId });
66	        return null;
67	      }
68	      throw error;
69	    }
70	  }
71	
72	  /**
73	   * Lists all events in a calendar within a date range
74	   */
75	  async listEvents(timeMin?: DateTime, timeMax?: DateTime): Promise<CalendarEvent[]> {
76	    winston.debug("Listing calendar events", { calendar: this.calendarId, timeMin, timeMax });
77	
78	    const response: any = await this.client.events.list({
79	      calendarId: this.calendarId,
80	      timeMin: timeMin?.toISO() ?? undefined,
81	      timeMax: timeMax?.toISO() ?? undefined,
82	      singleEvents: true,
83	      orderBy: "startTime",
84	    });
85	
86	    const events = response?.data?.items ?? [];
87	    winston.info(`Found ${events.length} events in calendar`);
88	
89	    return events
90	      .filter((event: any) => Boolean(event.start && event.id))
91	      .map((event: any) => convertToCalendarEvent(event));
92	  }
93	
94	  /**
95	   * Creates a new event in the calendar
96	   */
97	  async createEvent(calendarId: string, event: Omit<CalendarEvent, "id">): Promise<CalendarEvent> {
98	    winston.debug("Creating calendar event", { calendar: this.calendarId, event });
99	
100	    const response = await this.client.events.insert({
101	      calendarId,
102	      requestBody: convertToGoogleEvent(event),
103	    });
104	
105	    if (!response.data.id) {
106	      throw new Error("Failed to create event: no ID returned");
107	    }
108	
109	    winston.info("Created calendar event", { eventId: response.data.id });
110	    return convertToCalendarEvent(response.data);
111	  }
112	
113	  /**
114	   * Updates an existing event in the calendar
115	   */
116	  async updateEvent(calendarId: string, event: CalendarEvent): Promise<CalendarEvent> {
117	    winston.debug("Updating calendar event", { calendar: calendarId, eventId: event.id });
118	
119	    const response = await this.client.events.update({
120	      calendarId,
121	      eventId: event.id,
122	      requestBody: convertToGoogleEvent(event),
123	    });
124	
125	    if (!response.data.id) {
126	      throw new Error("Failed to update event: no ID returned");
127	    }
128	
129	    winston.info("Updated calendar event", { eventId: response.data.id });
130	    return convertToCalendarEvent(response.data);
131	  }
132	}
133	
134	function convertToCalendarEvent(event: calendar_v3.Schema$Event): CalendarEvent {
135	  const allDay = !event.start?.dateTime;
136	  const startTime = allDay ? DateTime.fromISO(event.start?.date ?? "") : DateTime.fromISO(event.start?.dateTime ?? "");
137	  const endTime = allDay ? DateTime.fromISO(event.end?.date ?? "") : DateTime.fromISO(event.end?.dateTime ?? "");
138	
139	  const calEvent: CalendarEvent = {
140	    id: event.id!,
141	    title: event.summary ?? "Untitled Event",
142	    startTime,
143	    endTime,
144	    allDay,
145	  };
146	
147	  if (event.description) {
148	    calEvent.description = event.description;
149	  }
150	  if (event.location) {
151	    calEvent.location = event.location;
152	  }
153	  if (event.extendedProperties?.private) {
154	    calEvent.metadata = event.extendedProperties.private as Record<string, string>;
155	  }
156	
157	  return calEvent;
158	}
159	
160	function convertToGoogleEvent(event: Partial<CalendarEvent>): calendar_v3.Schema$Event {
161	  const googleEvent: calendar_v3.Schema$Event = {
162	    summary: event.title ?? null,
163	    description: event.description ?? null,
164	    location: event.location ?? null,
165	  };
166	
167	  if (event.startTime && event.endTime) {
168	    if (event.allDay) {
169	      googleEvent.start = { date: event.startTime.toISODate() ?? null };
170	      googleEvent.end = { date: event.endTime.toISODate() ?? null };
171	    } else {
172	      googleEvent.start = { dateTime: event.startTime.toISO() ?? null };
173	      googleEvent.end = { dateTime: event.endTime.toISO() ?? null };
174	    }
175	  }
176	
177	  if (event.metadata) {
178	    googleEvent.extendedProperties = {
179	      private: event.metadata,
180	    };
181	  }
182	
183	  return googleEvent;
184	}
